import{actionIcon}from './action-icons.js';
const DAY=86400000;
const date=value=>{if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const n=Date.parse(value+'T00:00:00Z');return Number.isFinite(n)&&new Date(n).toISOString().slice(0,10)===value?n:null;};
const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const number=value=>value.toLocaleString('ru-RU');
export const activityDate=(day,full=false)=>new Intl.DateTimeFormat('ru-RU',{timeZone:'UTC',day:'numeric',month:full?'long':'short',...(full?{year:'numeric'}:{})}).format(new Date(date(day)));
const unit=value=>{const n=value%100;return n>=11&&n<=14?'посетителей':value%10===1?'посетитель':value%10>=2&&value%10<=4?'посетителя':'посетителей';};
export function ownerActivityModel(stats,period=7,selectedDay=null){
 if(![1,7,30].includes(period)||!Number.isSafeInteger(stats?.total)||stats.total<0||!Array.isArray(stats.stats))throw Error('Статистика временно недоступна.');
 const unique=new Map();for(const row of stats.stats){if(date(row?.day)===null||!Number.isSafeInteger(row.visitors)||row.visitors<0)continue;if(unique.has(row.day)&&unique.get(row.day)!==row.visitors)throw Error('Не удалось проверить даты статистики.');unique.set(row.day,row.visitors);}
 const source=[...unique].sort(([a],[b])=>a.localeCompare(b)),last=source.at(-1)?.[0],end=last?date(last):null,start=end===null?null:Math.max(date(source[0][0]),end-period*DAY),rows=[];
 if(end!==null)for(let n=start;n<=end;n+=DAY){const day=new Date(n).toISOString().slice(0,10);rows.push({day,visitors:unique.has(day)?unique.get(day):null});}
 const max=Math.max(1,...rows.map(r=>r.visitors||0)),sum=rows.reduce((n,r)=>n+(r.visitors||0),0),peak=rows.reduce((best,row)=>row.visitors!==null&&(!best||row.visitors>best.visitors)?row:best,null),index=rows.findIndex(r=>r.day===selectedDay);
 const updated=new Date(stats.updatedAt),time=Number.isFinite(updated.getTime())?updated.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'';
 return{period,total:stats.total,average:!rows.length||rows.some(r=>r.visitors===null)?null:Math.round(sum/period),rows,max,peak,index:index<0?rows.length-1:index,time};
}
function pointLabel(row){return activityDate(row.day,true)+' · '+(row.visitors===null?'нет данных':number(row.visitors)+' '+unit(row.visitors));}
export function ownerActivityView(stats,period=7,selectedDay=null,reportLink=''){
 const m=ownerActivityModel(stats,period,selectedDay),picked=m.rows[m.index],periodLabel=period===1?'За 24 часа':'За '+period+' дней',range=m.rows.length?activityDate(m.rows[0].day)+' — '+activityDate(m.rows.at(-1).day):'Выбранный период';
 return{model:m,html:'<div class="owner-activity-summary"><div><span>'+periodLabel+'</span><strong>'+number(m.total)+'</strong><small>'+esc(range)+'</small></div><div><span>Пик за день</span><strong>'+(m.peak?number(m.peak.visitors):'—')+'</strong><small>'+(m.peak?esc(activityDate(m.peak.day)):'Нет данных')+'</small></div></div>'+(!picked?'<div class="owner-activity-empty"><p>За выбранный период пока нет данных.</p></div>':'<section class="owner-activity-card"><div class="owner-activity-chart-title"><h2>По дням</h2><button type="button" class="text-button" data-activity-peak aria-label="Показать самый активный день">К максимуму</button></div><div class="owner-activity-picked"><button type="button" data-activity-step="-1" aria-label="Предыдущий день">'+actionIcon('back')+'</button><div role="status" aria-live="polite" aria-atomic="true"><time data-activity-day datetime="'+picked.day+'">'+esc(activityDate(picked.day,true))+'</time><strong data-activity-value>'+(picked.visitors===null?'Нет данных':number(picked.visitors)+' <small>'+unit(picked.visitors)+'</small>')+'</strong></div><button type="button" data-activity-step="1" aria-label="Следующий день">'+actionIcon('next')+'</button></div><div class="owner-activity-plot" role="group" aria-label="Посетители по дням"><div class="owner-activity-bars" aria-hidden="true">'+m.rows.map((row,i)=>'<span class="owner-activity-bar'+(i===m.index?' is-selected':'')+(row.visitors===null?' is-missing':'')+'" style="--bar-height:'+Math.max(1,Math.round((row.visitors||0)/m.max*100))+'%"></span>').join('')+'</div><input type="range" min="0" max="'+(m.rows.length-1)+'" value="'+m.index+'" step="1" aria-label="День на графике" aria-valuetext="'+esc(pointLabel(picked))+'"'+(m.rows.length===1?' disabled':'')+'></div><div class="owner-activity-axis" aria-hidden="true"><span>'+esc(activityDate(m.rows[0].day))+'</span>'+(m.rows.length>3?'<span>'+esc(activityDate(m.rows[Math.floor((m.rows.length-1)/2)].day))+'</span>':'')+'<span>'+esc(activityDate(m.rows.at(-1).day))+'</span></div><p class="owner-activity-hint">Коснитесь графика или проведите по нему</p></section>')+'<div class="owner-activity-footer"><span>'+(m.time?'Обновлено в '+esc(m.time):'')+'</span><details class="owner-activity-info"><summary>О данных</summary><p>Здесь показаны посетители сайта. За период — уникальные посетители. Один человек может отмечаться в разные дни, поэтому дневные значения не складываются в общий итог. Активность аккаунтов приложения доступна в «Пользователях».</p>'+reportLink+'</details></div>'};
}
export function bindOwnerActivity(host,model,{onSelect=()=>{}}={}){
 const input=host.querySelector('input[type=range]');if(!input)return()=>{};let index=model.index;
 const previous=host.querySelector('[data-activity-step="-1"]'),next=host.querySelector('[data-activity-step="1"]'),peak=host.querySelector('[data-activity-peak]'),bars=[...host.querySelectorAll('.owner-activity-bar')];
 const select=value=>{index=Math.max(0,Math.min(model.rows.length-1,Number(value)||0));const row=model.rows[index];input.value=String(index);input.setAttribute('aria-valuetext',pointLabel(row));const day=host.querySelector('[data-activity-day]'),count=host.querySelector('[data-activity-value]');day.dateTime=row.day;day.textContent=activityDate(row.day,true);count.innerHTML=row.visitors===null?'Нет данных':number(row.visitors)+' <small>'+unit(row.visitors)+'</small>';bars.forEach((bar,i)=>bar.classList.toggle('is-selected',i===index));previous.disabled=index===0;next.disabled=index===model.rows.length-1;onSelect(row.day);};
 const change=()=>select(input.value),prevClick=()=>select(index-1),nextClick=()=>select(index+1),peakClick=()=>select(model.rows.findIndex(r=>r.day===model.peak?.day));
 input.addEventListener('input',change);previous.addEventListener('click',prevClick);next.addEventListener('click',nextClick);peak.addEventListener('click',peakClick);select(index);
 return()=>{input.removeEventListener('input',change);previous.removeEventListener('click',prevClick);next.removeEventListener('click',nextClick);peak.removeEventListener('click',peakClick);};
}
